// Generated by scripts/generate-phone-theme.ts from the built-in color themes (src/shared/colorThemes.ts).

/// A built-in color theme, under its maker's name in every language, in the order Settings lists them.
public enum PhoneColorTheme: String, CaseIterable, Sendable {
    case rosePine = "rose-pine"
    case rosePineMoon = "rose-pine-moon"
    case rosePineDawn = "rose-pine-dawn"
    case catppuccinLatte = "catppuccin-latte"
    case catppuccinFrappe = "catppuccin-frappe"
    case catppuccinMacchiato = "catppuccin-macchiato"
    case catppuccinMocha = "catppuccin-mocha"
    case oneDark = "one-dark"
    case oneLight = "one-light"
    case dracula = "dracula"
    case nightOwl = "night-owl"
    case nightOwlLight = "night-owl-light"
    case tokyoNight = "tokyo-night"

    /// Its maker's name, shown untranslated.
    public var name: String {
        switch self {
        case .rosePine: "Rosé Pine"
        case .rosePineMoon: "Rosé Pine Moon"
        case .rosePineDawn: "Rosé Pine Dawn"
        case .catppuccinLatte: "Catppuccin Latte"
        case .catppuccinFrappe: "Catppuccin Frappé"
        case .catppuccinMacchiato: "Catppuccin Macchiato"
        case .catppuccinMocha: "Catppuccin Mocha"
        case .oneDark: "One Dark"
        case .oneLight: "One Light"
        case .dracula: "Dracula"
        case .nightOwl: "Night Owl"
        case .nightOwlLight: "Night Owl Light"
        case .tokyoNight: "Tokyo Night"
        }
    }

    /// Whether it sits on Dark; otherwise it sits on Light.
    public var isDark: Bool {
        switch self {
        case .rosePine: true
        case .rosePineMoon: true
        case .rosePineDawn: false
        case .catppuccinLatte: false
        case .catppuccinFrappe: true
        case .catppuccinMacchiato: true
        case .catppuccinMocha: true
        case .oneDark: true
        case .oneLight: false
        case .dracula: true
        case .nightOwl: true
        case .nightOwlLight: false
        case .tokyoNight: true
        }
    }
}
